INSERT INTO `Pages` VALUES
(1,'dashboard','Dashboard','Main','<div class=\"container\">\n    <h1>Welcome to the Dashboard</h1>\n    <p>This page is rendered entirely from the database!</p>\n    <p>The current server time is: <?php echo date(\'Y-m-d H:i:s\'); ?></p>\n    \n    <div class=\"menu\">\n        <a href=\"?page=page_manager\">Manage Content</a>\n    </div>\n\n    <p>This system allows you to manage all pages, CSS, and JavaScript directly from the database via the content manager.</p>\n</div>',NULL),
(2,'page_manager','Content Manager','Tools','<?php\n// This is the self-contained code for the Page Manager.\n// It will be inserted into the `Pages` table.\n// It assumes the $pdo variable is available, as provided by index.php.\n\n// --- Security & Configuration ---\n// Helper function for rendering safe HTML\nfunction e($string) {\n    return htmlspecialchars($string, ENT_QUOTES, \'UTF-8\');\n}\n\n$base_url = \'?page=page_manager\';\n\n// --- Action Handling ---\n$action = $_GET[\'action\'] ?? \'list\'; // Default action is to list everything\n$type = $_GET[\'type\'] ?? null;\n$id = isset($_GET[\'id\']) ? (int)$_GET[\'id\'] : null;\n$message = \'\';\n\n// --- Handle POST requests for saving/creating/deleting ---\nif ($_SERVER[\'REQUEST_METHOD\'] === \'POST\') {\n    $post_action = $_POST[\'action\'] ?? \'\';\n    $post_type = $_POST[\'type\'] ?? \'\';\n    $post_id = isset($_POST[\'id\']) ? (int)$_POST[\'id\'] : null;\n\n    try {\n        if ($post_action === \'save\') {\n            $table_name = \'\';\n            if ($post_type === \'page\') $table_name = \'Pages\';\n            if ($post_type === \'css\') $table_name = \'CSS_Files\';\n            if ($post_type === \'js\') $table_name = \'JS_Files\';\n\n            if ($table_name) {\n                if ($post_id) { // Update existing\n                    $stmt = $pdo->prepare(\"UPDATE `$table_name` SET `name` = ?, `code` = ? WHERE `id` = ?\");\n                    $stmt->execute([$_POST[\'name\'], $_POST[\'code\'], $post_id]);\n                    $message = \"<p style=\'color: #2ecc71;\'>Successfully updated $post_type #$post_id.</p>\";\n                } else { // Create new\n                    $stmt = $pdo->prepare(\"INSERT INTO `$table_name` (`name`, `code`) VALUES (?, ?)\");\n                    $stmt->execute([$_POST[\'name\'], $_POST[\'code\']]);\n                    $new_id = $pdo->lastInsertId();\n                    $message = \"<p style=\'color: #2ecc71;\'>Successfully created $post_type #$new_id.</p>\";\n                }\n            }\n        } elseif ($post_action === \'delete\') {\n            $table_name = \'\';\n            if ($post_type === \'page\') $table_name = \'Pages\';\n            if ($post_type === \'css\') $table_name = \'CSS_Files\';\n            if ($post_type === \'js\') $table_name = \'JS_Files\';\n\n            if ($table_name && $post_id) {\n                // You might want to add checks here to prevent deleting linked items\n                $stmt = $pdo->prepare(\"DELETE FROM `$table_name` WHERE `id` = ?\");\n                $stmt->execute([$post_id]);\n                $message = \"<p style=\'color: #e74c3c;\'>Successfully deleted $post_type #$post_id.</p>\";\n            }\n        }\n    } catch (PDOException $e) {\n        $message = \"<p style=\'color: #e74c3c;\'>Database Error: \" . e($e->getMessage()) . \"</p>\";\n    }\n    // Redirect to the list view after a POST action to prevent form re-submission\n    header(\"Location: $base_url&message=\" . urlencode(base64_encode($message)));\n    exit;\n}\n\nif (isset($_GET[\'message\'])) {\n    $message = base64_decode($_GET[\'message\']);\n}\n\n// --- Display Logic ---\n?>\n<div class=\"container\">\n    <h1>Page Content Manager</h1>\n    <div class=\"menu\">\n        <a href=\"?page=dashboard\">Back to Dashboard</a>\n    </div>\n\n    <?php echo $message; ?>\n\n    <?php if ($action === \'list\'): ?>\n        <!-- LIST VIEW -->\n        <div style=\"display: flex; gap: 2rem;\">\n            <div style=\"flex: 1;\">\n                <h2>Pages</h2>\n                <a href=\"<?php echo $base_url; ?>&action=edit&type=page\">Create New Page</a>\n                <ul style=\"list-style: none; padding-left: 0;\">\n                    <?php foreach ($pdo->query(\"SELECT id, name FROM Pages ORDER BY name\") as $row): ?>\n                        <li><a href=\"<?php echo $base_url; ?>&action=edit&type=page&id=<?php echo $row[\'id\']; ?>\"><?php echo e($row[\'name\']); ?></a></li>\n                    <?php endforeach; ?>\n                </ul>\n            </div>\n            <div style=\"flex: 1;\">\n                <h2>CSS Files</h2>\n                <a href=\"<?php echo $base_url; ?>&action=edit&type=css\">Create New CSS</a>\n                <ul style=\"list-style: none; padding-left: 0;\">\n                    <?php foreach ($pdo->query(\"SELECT id, name FROM CSS_Files ORDER BY name\") as $row): ?>\n                        <li><a href=\"<?php echo $base_url; ?>&action=edit&type=css&id=<?php echo $row[\'id\']; ?>\"><?php echo e($row[\'name\']); ?></a></li>\n                    <?php endforeach; ?>\n                </ul>\n            </div>\n            <div style=\"flex: 1;\">\n                <h2>JS Files</h2>\n                <a href=\"<?php echo $base_url; ?>&action=edit&type=js\">Create New JS</a>\n                 <ul style=\"list-style: none; padding-left: 0;\">\n                    <?php foreach ($pdo->query(\"SELECT id, name FROM JS_Files ORDER BY name\") as $row): ?>\n                        <li><a href=\"<?php echo $base_url; ?>&action=edit&type=js&id=<?php echo $row[\'id\']; ?>\"><?php echo e($row[\'name\']); ?></a></li>\n                    <?php endforeach; ?>\n                </ul>\n            </div>\n        </div>\n\n    <?php elseif ($action === \'edit\' && $type): ?>\n        <!-- EDIT/CREATE VIEW -->\n        <?php\n        $item = null;\n        $table_name = \'\';\n        if ($type === \'page\') $table_name = \'Pages\';\n        if ($type === \'css\') $table_name = \'CSS_Files\';\n        if ($type === \'js\') $table_name = \'JS_Files\';\n\n        if ($id && $table_name) {\n            $stmt = $pdo->prepare(\"SELECT * FROM `$table_name` WHERE id = ?\");\n            $stmt->execute([$id]);\n            $item = $stmt->fetch();\n        }\n        $page_title = $id ? \"Editing $type #\" . e($id) : \"Creating New $type\";\n        ?>\n        <h2><?php echo $page_title; ?></h2>\n        <a href=\"<?php echo $base_url; ?>\">&larr; Back to list</a>\n        \n        <form action=\"<?php echo $base_url; ?>\" method=\"POST\" style=\"margin-top: 1rem;\">\n            <input type=\"hidden\" name=\"action\" value=\"save\">\n            <input type=\"hidden\" name=\"type\" value=\"<?php echo e($type); ?>\">\n            <input type=\"hidden\" name=\"id\" value=\"<?php echo e($id); ?>\">\n            \n            <div style=\"margin-bottom: 1rem;\">\n                <label for=\"name\" style=\"display: block; margin-bottom: 5px;\">Name:</label>\n                <input type=\"text\" id=\"name\" name=\"name\" value=\"<?php echo e($item[\'name\'] ?? \'\'); ?>\" required style=\"width: 100%; padding: 8px; background: #333; color: #fff; border: 1px solid #555;\">\n            </div>\n            <div style=\"margin-bottom: 1rem;\">\n                <label for=\"code\" style=\"display: block; margin-bottom: 5px;\">Code:</label>\n                <textarea id=\"code\" name=\"code\" rows=\"25\" style=\"width: 100%; padding: 8px; background: #333; color: #fff; border: 1px solid #555; font-family: monospace;\"><?php echo e($item[\'code\'] ?? \'\'); ?></textarea>\n            </div>\n            <div>\n                <button type=\"submit\" style=\"padding: 10px 20px; background: #2ecc71; color: white; border: none; cursor: pointer;\">Save Changes</button>\n            </div>\n        </form>\n\n        <?php if ($id): ?>\n        <form action=\"<?php echo $base_url; ?>\" method=\"POST\" onsubmit=\"return confirm(\'Are you sure you want to delete this?\');\" style=\"margin-top: 2rem;\">\n             <input type=\"hidden\" name=\"action\" value=\"delete\">\n             <input type=\"hidden\" name=\"type\" value=\"<?php echo e($type); ?>\">\n             <input type=\"hidden\" name=\"id\" value=\"<?php echo e($id); ?>\">\n             <button type=\"submit\" style=\"padding: 10px 20px; background: #e74c3c; color: white; border: none; cursor: pointer;\">Delete <?php echo e($type); ?></button>\n        </form>\n        <?php endif; ?>\n\n    <?php endif; ?>\n</div>',NULL),
(4,'invoices/list','List Invoices','Invoices','<?php\n$pdo = DB::conn();\necho \"<h1>Invoices</h1>\";\n\n$sql = \"SELECT i.id, i.invoice_no, i.invoice_date, i.party_name, i.inv_type, i.status,\n               COALESCE(SUM(it.line_total)) AS total\n        FROM invoices i\n        LEFT JOIN invoice_items it ON i.id = it.invoice_id\n        GROUP BY i.id, i.invoice_no, i.invoice_date, i.party_name, i.inv_type, i.status\n        ORDER BY i.invoice_date DESC, i.id DESC\n        LIMIT 50\";\n\n$stmt = $pdo->query($sql);\n\necho \"<table border=1 cellpadding=6>\n<tr>\n  <th>ID</th>\n  <th>No</th>\n  <th>Date</th>\n  <th>Party</th>\n  <th>Type</th>\n  <th>Status</th>\n  <th>Total</th>\n</tr>\";\n\nforeach ($stmt as $row) {\n    echo \"<tr>\n        <td>{$row[\"id\"]}</td>\n        <td>\".htmlspecialchars($row[\"invoice_no\"]).\"</td>\n        <td>{$row[\"invoice_date\"]}</td>\n        <td>\".htmlspecialchars($row[\"party_name\"]).\"</td>\n        <td>{$row[\"inv_type\"]}</td>\n        <td>{$row[\"status\"]}</td>\n        <td style=\"text-align:right;\">\".number_format($row[\"total\"]).\"</td>\n    </tr>\";\n}\necho \"</table>\";\n;?>','invoices,invoice_items'),
(19,'tools/manual-refresh-reminder','Manual Refresh Reminder','Tools','<?php\n$pdo = DB::conn();\n$stmt = $pdo->prepare(\"SELECT setting_value FROM app_settings WHERE setting_key = ?\");\n$stmt->execute([\"dependency_refresh_command\"]);\n$cmd = $stmt->fetchColumn() ?: \"Command not configured.\";\n;?>\n<!DOCTYPE html>\n<html>\n<head>\n  <meta charset=\"UTF-8\">\n  <title>Manual Refresh Reminder</title>\n  <style>\n    body { font-family: Arial, sans-serif; background: #fff8dc; color: #333; padding: 20px; }\n    pre { background: #eee; padding: 12px; border-radius: 6px; }\n  </style>\n</head>\n<body>\n  <h1>🚨 Manual Dependency Refresh 🚨</h1>\n  <p>Run this command manually to refresh <b>tables_used</b> and rebuild dependency views:</p>\n  <pre><?php echo htmlspecialchars($cmd); ;?></pre>\n  <p>Copy and paste into your terminal whenever you need to refresh.</p>\n</body>\n</html>','app_settings'),
(30,'tools/diagnostics','Diagnostics','Tools','<?php\n$pdo = DB::conn();\n\necho \"<h1>Diagnostics</h1>\";\n\n// Filters\n$level = $_GET[\"level\"] ?? \"\";\n$limit = (int)($_GET[\"limit\"] ?? 100);\nif ($limit <= 0 || $limit > 1000) $limit = 100;\n\n$where = \"\";\n$params = [];\nif (in_array($level, [\"INFO\",\"WARN\",\"ERROR\"])) {\n    $where = \"WHERE level = ?\";\n    $params[] = $level;\n}\n\n// Fetch logs\n$sql = \"SELECT id, created_at, level, message FROM diagnostics \" . $where . \" ORDER BY id DESC LIMIT ?\";\n$stmt = $pdo->prepare($sql);\nforeach ($params as $idx => $val) {\n    $stmt->bindValue($idx+1, $val);\n}\n$stmt->bindValue(count($params)+1, $limit, PDO::PARAM_INT);\n$stmt->execute();\n\necho \"<form method=\\\"get\\\">\n  <input type=\\\"hidden\\\" name=\\\"page\\\" value=\\\"tools/diagnostics\\\">\n  Level: \n  <select name=\\\"level\\\">\n    <option value=\\\"\\\">(All)</option>\n    <option value=\\\"INFO\\\" \".($level===\"INFO\"?\"selected\":\"\").\">INFO</option>\n    <option value=\\\"WARN\\\" \".($level===\"WARN\"?\"selected\":\"\").\">WARN</option>\n    <option value=\\\"ERROR\\\" \".($level===\"ERROR\"?\"selected\":\"\").\">ERROR</option>\n  </select>\n  Limit: <input name=\\\"limit\\\" value=\\\"\".$limit.\"\\\" size=\\\"4\\\">\n  <button type=\\\"submit\\\">Apply</button>\n</form>\";\n\necho \"<table border=1 cellpadding=6>\n<tr>\n  <th>ID</th>\n  <th>Time</th>\n  <th>Level</th>\n  <th>Message</th>\n</tr>\";\n\nforeach ($stmt as $row) {\n    echo \"<tr>\n      <td>\".$row[\"id\"].\"</td>\n      <td>\".$row[\"created_at\"].\"</td>\n      <td>\".$row[\"level\"].\"</td>\n      <td><pre style=\\\"margin:0;white-space:pre-wrap;\\\">\".htmlspecialchars($row[\"message\"]).\"</pre></td>\n    </tr>\";\n}\necho \"</table>\";\n\n// Quick self-test: log an INFO message (optional button)\nif ($_SERVER[\"REQUEST_METHOD\"] === \"POST\" && isset($_POST[\"self_test\"])) {\n    try {\n        $log = $pdo->prepare(\"INSERT INTO diagnostics (level, message) VALUES (?, ?)\");\n        $log->execute([\"INFO\", \"Self-test: diagnostics page is working\"]);\n        echo \"<p style=\\\"color:green;\\\">Self-test log inserted.</p>\";\n    } catch (Exception $e) {\n        echo \"<p style=\\\"color:red;\\\">Self-test failed: \".htmlspecialchars($e->getMessage()).\"</p>\";\n    }\n}\necho \"<form method=\\\"post\\\"><button name=\\\"self_test\\\" value=\\\"1\\\">Insert self-test log</button></form>\";\n;?>','diagnostics'),
(31,'parties/master','Party Master','Parties','<?php\n$pdo = DB::conn();\n\nif ($_SERVER[\"REQUEST_METHOD\"] === \"POST\") {\n    try {\n        $stmt = $pdo->prepare(\"INSERT INTO parties (name, gstin, party_type, city, state, state_code) VALUES (?,?,?,?,?,?)\");\n        $stmt->execute([\n            $_POST[\"name\"],\n            $_POST[\"gstin\"] ?: null,\n            $_POST[\"party_type\"],\n            $_POST[\"city\"] ?: null,\n            $_POST[\"state\"] ?: null,\n            $_POST[\"state_code\"] ?: null\n        ]);\n        echo \"<p style=\"color:green;\">Party saved successfully.</p>\";\n    } catch (Exception $e) {\n        echo \"<p style=\"color:red;\">Error: \".htmlspecialchars($e->getMessage()).\"</p>\";\n    }\n}\n\necho \"<h1>Party Master</h1>\";\necho \"<form method=post>\n  <label>Name: <input name=name required></label><br>\n  <label>GSTIN: <input name=gstin maxlength=15></label><br>\n  <label>Type: \n    <select name=party_type>\n      <option value=\"customer\">Customer</option>\n      <option value=\"supplier\">Supplier</option>\n      <option value=\"both\">Both</option>\n    </select>\n  </label><br>\n  <label>City: <input name=city></label><br>\n  <label>State: <input name=state></label><br>\n  <label>State Code: <input name=state_code maxlength=2></label><br>\n  <button type=submit>Save</button>\n</form>\";\n\necho \"<h2>Existing Parties</h2>\";\n$stmt = $pdo->query(\"SELECT id, name, gstin, party_type, city, state, state_code FROM parties ORDER BY id DESC LIMIT 20\");\necho \"<table border=1 cellpadding=6><tr><th>ID</th><th>Name</th><th>GSTIN</th><th>Type</th><th>City</th><th>State</th><th>Code</th></tr>\";\nforeach ($stmt as $row) {\n    echo \"<tr>\n        <td>{$row[\"id\"]}</td>\n        <td>\".htmlspecialchars($row[\"name\"]).\"</td>\n        <td>\".htmlspecialchars($row[\"gstin\"]).\"</td>\n        <td>{$row[\"party_type\"]}</td>\n        <td>\".htmlspecialchars($row[\"city\"]).\"</td>\n        <td>\".htmlspecialchars($row[\"state\"]).\"</td>\n        <td>\".htmlspecialchars($row[\"state_code\"]).\"</td>\n    </tr>\";\n}\necho \"</table>\";\n;?>','parties'),
(36,'invoices/view','View Invoice','Invoices','<?php\n$pdo = DB::conn();\n\n$invoiceId = $_GET[\"id\"] ?? null;\nif (!$invoiceId) {\n    echo \"<p style=\"color:red;\">No invoice ID provided.</p>\";\n    return;\n}\n\n// Fetch invoice header\n$stmt = $pdo->prepare(\"SELECT * FROM invoices WHERE id=?\");\n$stmt->execute([$invoiceId]);\n$inv = $stmt->fetch(PDO::FETCH_ASSOC);\n\nif (!$inv) {\n    echo \"<p style=\"color:red;\">Invoice not found.</p>\";\n    return;\n}\n\necho \"<h1>Invoice #\".htmlspecialchars($inv[\"invoice_no\"]).\"</h1>\";\necho \"<p>Date: \".$inv[\"invoice_date\"].\"</p>\";\necho \"<p>Party: \".htmlspecialchars($inv[\"party_name\"]).\" (GSTIN: \".htmlspecialchars($inv[\"party_gstin\"]).\")</p>\";\necho \"<p>Type: \".$inv[\"inv_type\"].\" | Status: \".$inv[\"status\"].\"</p>\";\n\n// Fetch items\n$stmt = $pdo->prepare(\"SELECT description, hsn, quantity, rate, cgst_rate, sgst_rate, igst_rate, line_total \n                       FROM invoice_items WHERE invoice_id=?\");\n$stmt->execute([$invoiceId]);\n\necho \"<h2>Items</h2>\";\necho \"<table border=1 cellpadding=6>\n<tr>\n  <th>Description</th>\n  <th>HSN</th>\n  <th>Qty</th>\n  <th>Rate</th>\n  <th>CGST%</th>\n  <th>SGST%</th>\n  <th>IGST%</th>\n  <th>Line Total</th>\n</tr>\";\n\n$total = 0;\nforeach ($stmt as $row) {\n    $total += $row[\"line_total\"];\n    echo \"<tr>\n        <td>\".htmlspecialchars($row[\"description\"]).\"</td>\n        <td>\".htmlspecialchars($row[\"hsn\"]).\"</td>\n        <td>\".$row[\"quantity\"].\"</td>\n        <td>\".$row[\"rate\"].\"</td>\n        <td>\".$row[\"cgst_rate\"].\"</td>\n        <td>\".$row[\"sgst_rate\"].\"</td>\n        <td>\".$row[\"igst_rate\"].\"</td>\n        <td style=\"text-align:right;\">\".number_format($row[\"line_total\"]).\"</td>\n    </tr>\";\n}\necho \"<tr><td colspan=7 style=\"text-align:right;\"><strong>Total</strong></td>\n      <td style=\"text-align:right;\"><strong>\".number_format($total).\"</strong></td></tr>\";\necho \"</table>\";\n\necho \"<p><a href=\"new_index.php?page=invoices/list\">Back to list</a></p>\";\n;?>','invoices,invoice_items'),
(37,'invoices/print','Print Invoice','Invoices','<?php\n$pdo = DB::conn();\n\n$invoiceId = $_GET[\"id\"] ?? null;\nif (!$invoiceId) {\n    echo \"<p style=\"color:red;\">No invoice ID provided.</p>\";\n    return;\n}\n\n// Fetch invoice header\n$stmt = $pdo->prepare(\"SELECT * FROM invoices WHERE id=?\");\n$stmt->execute([$invoiceId]);\n$inv = $stmt->fetch(PDO::FETCH_ASSOC);\n\nif (!$inv) {\n    echo \"<p style=\"color:red;\">Invoice not found.</p>\";\n    return;\n}\n\n// Fetch items\n$stmt = $pdo->prepare(\"SELECT description, hsn, quantity, rate, cgst_rate, sgst_rate, igst_rate, line_total \n                       FROM invoice_items WHERE invoice_id=?\");\n$stmt->execute([$invoiceId]);\n$items = $stmt->fetchAll(PDO::FETCH_ASSOC);\n\n// Print‑friendly HTML;?>\n<!DOCTYPE html>\n<html>\n<head>\n  <meta charset=\"UTF-8\">\n  <title>Invoice #<?php echo htmlspecialchars($inv[\"invoice_no\"]); ;?></title>\n  <style>\n    body { font-family: Arial, sans-serif; margin: 40px; color: #000; }\n    h1, h2 { margin: 0; }\n    .header { display: flex; justify-content: space-between; margin-bottom: 20px; }\n    .party { margin-top: 10px; }\n    table { border-collapse: collapse; width: 100%; margin-top: 20px; }\n    th, td { border: 1px solid #000; padding: 6px; text-align: left; }\n    th { background: #f0f0f0; }\n    .total-row td { font-weight: bold; }\n    @media print {\n      button { display: none; }\n    }\n  </style>\n</head>\n<body>\n  <div class=\"header\">\n    <div>\n      <h1>Invoice</h1>\n      <p>No: <?php echo htmlspecialchars($inv[\"invoice_no\"]); ;?><br>\n         Date: <?php echo $inv[\"invoice_date\"]; ;?><br>\n         Type: <?php echo $inv[\"inv_type\"]; ;?></p>\n    </div>\n    <div>\n      <h2><?php echo htmlspecialchars($inv[\"party_name\"]); ;?></h2>\n      <p class=\"party\">\n        GSTIN: <?php echo htmlspecialchars($inv[\"party_gstin\"]); ;?><br>\n        City: <?php echo htmlspecialchars($inv[\"city\"]); ;?><br>\n        State: <?php echo htmlspecialchars($inv[\"state\"]); ;?>\n      </p>\n    </div>\n  </div>\n\n  <table>\n    <tr>\n      <th>Description</th>\n      <th>HSN</th>\n      <th>Qty</th>\n      <th>Rate</th>\n      <th>CGST%</th>\n      <th>SGST%</th>\n      <th>IGST%</th>\n      <th>Line Total</th>\n    </tr>\n    <?php $grand=0; foreach ($items as $row): $grand += $row[\"line_total\"]; ;?>\n    <tr>\n      <td><?php echo htmlspecialchars($row[\"description\"]); ;?></td>\n      <td><?php echo htmlspecialchars($row[\"hsn\"]); ;?></td>\n      <td><?php echo $row[\"quantity\"]; ;?></td>\n      <td><?php echo number_format($row[\"rate\"]); ;?></td>\n      <td><?php echo $row[\"cgst_rate\"]; ;?></td>\n      <td><?php echo $row[\"sgst_rate\"]; ;?></td>\n      <td><?php echo $row[\"igst_rate\"]; ;?></td>\n      <td style=\"text-align:right;\"><?php echo number_format($row[\"line_total\"]); ;?></td>\n    </tr>\n    <?php endforeach; ;?>\n    <tr class=\"total-row\">\n      <td colspan=\"7\" style=\"text-align:right;\">Grand Total</td>\n      <td style=\"text-align:right;\"><?php echo number_format($grand); ;?></td>\n    </tr>\n  </table>\n\n  <button onclick=\"window.print()\">🖨 Print</button>\n</body>\n</html>\n<?php;?>','invoices,invoice_items,parties'),
(38,'tools/gst-summary','GST Summary','Tools','<?php\n$pdo = DB::conn();\n\necho \"<h1>GST Summary</h1>\";\n\n$sql = \"SELECT \n            DATE_FORMAT(i.invoice_date, \'%Y-%m\') AS period,\n            SUM(it.taxable_amount) AS taxable_value,\n            SUM(it.cgst_amount) AS cgst_total,\n            SUM(it.sgst_amount) AS sgst_total,\n            SUM(it.igst_amount) AS igst_total,\n            SUM(it.line_total) AS grand_total\n        FROM invoices i\n        JOIN invoice_items it ON i.id = it.invoice_id\n        WHERE i.status <> \'cancelled\'\n        GROUP BY DATE_FORMAT(i.invoice_date, \'%Y-%m\')\n        ORDER BY period DESC\";\n\n$stmt = $pdo->query($sql);\n\necho \"<table border=1 cellpadding=6>\n<tr>\n  <th>Period (YYYY-MM)</th>\n  <th>Taxable Value</th>\n  <th>CGST</th>\n  <th>SGST</th>\n  <th>IGST</th>\n  <th>Grand Total</th>\n</tr>\";\n\nforeach ($stmt as $row) {\n    echo \"<tr>\n        <td>{$row[\"period\"]}</td>\n        <td style=\"text-align:right;\">\".number_format($row[\"taxable_value\"]).\"</td>\n        <td style=\"text-align:right;\">\".number_format($row[\"cgst_total\"]).\"</td>\n        <td style=\"text-align:right;\">\".number_format($row[\"sgst_total\"]).\"</td>\n        <td style=\"text-align:right;\">\".number_format($row[\"igst_total\"]).\"</td>\n        <td style=\"text-align:right;\">\".number_format($row[\"grand_total\"]).\"</td>\n    </tr>\";\n}\necho \"</table>\";\n;?>','invoices,invoice_items');
